SELECT pancreactomy1_1.nppes_provider_city AS nppes_provider_city,   pancreactomy1_1.nppes_provider_gender AS nppes_provider_gender,   pancreactomy1_1.nppes_provider_last_org_name AS nppes_provider_last_org_name,   pancreactomy1_1.nppes_provider_state AS nppes_provider_state,   pancreactomy1_1.provider_type AS provider_type,   SUM(pancreactomy1_1.line_srvc_cnt) AS sum_line_srvc_cnt_ok FROM pancreactomy1_1 WHERE ((pancreactomy1_1.provider_type IN ('General Surgery', 'Surgical Oncology')) AND (pancreactomy1_1.hcpcs_description IN ('Pancreas procedure', 'Partial removal of pancreas', 'Partial removal of pancreas with attachment to small bowel', 'Partial removal of pancreas, bile duct and small bowel with connection of pancreas to small bowel'))) GROUP BY pancreactomy1_1.nppes_provider_city,   pancreactomy1_1.nppes_provider_gender,   pancreactomy1_1.nppes_provider_last_org_name,   pancreactomy1_1.nppes_provider_state,   pancreactomy1_1.provider_type;
